    expected_keys = {
        "name",
        "description",
        "query",
    }
    extra_keys = set(update_data.keys()) - expected_keys

    if extra_keys:
        raise ValidationError(f"Can't update keys: {', '.join(sorted(extra_keys))} on ExperimentSavedMetric")

